-- MAIL-08/09: koyu temalı, marka paletli yeni e-posta tasarımı (şablon sürümü 2) ve sitenin "sen" diliyle TR metinler.
-- Kabuk (wordmark başlığı, altbilgi, imza çizgisi, açık tema iyileştirmesi) mail/layout.html ve TemplateRenderer içindedir;
-- buradaki gövdeler yalnız içerik bileşenleridir (etiket, başlık, kod kutusu, düğme, tarih kutusu, uyarı kutusu).
-- EN konu ve düz metin sürüm 1 ile AYNIDIR; TR metinler "siz" yerine "sen" kipine çevrildi (siteyle aynı ses).
-- V82/V83 değiştirilmez: sürüm 2 satırları eklenir, sürüm 1 pasife alınır (geri dönüş için satırlar kalır).
-- Kullanılabilen değişkenler: code, link, validityMinutes, occurredAt.

INSERT INTO mail_templates (id, code, locale, subject, body_html, body_text, version, active, created_at, updated_at)
SELECT gen_random_uuid(), t.code, t.locale, t.subject, t.body_html, t.body_text, 2, true, now(), now()
FROM (VALUES
('EMAIL_VERIFICATION', 'tr',
 $s$LTZ e-posta doğrulama kodun$s$,
 $h$<p class="eb-accent" style="margin:0 0 10px 0;font-family:'Chakra Petch','Bahnschrift','Segoe UI',Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:2.5px;color:#ff2e88">E-POSTA DOĞRULAMA</p><h1 class="h1" style="margin:0 0 16px 0;font-family:'Chakra Petch','Bahnschrift','Segoe UI',Arial,sans-serif;font-size:28px;line-height:1.2;font-weight:700;color:#f1f1f1">E-posta adresini doğrula</h1><p style="margin:0 0 18px 0">LTZ hesabını doğrulamak için aşağıdaki kodu gir. Kod {{validityMinutes}} dakika geçerli.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 20px 0"><tr><td class="box" align="center" style="padding:20px 16px;background:#1e1f26;border:1px solid #34343c;border-radius:12px"><p class="muted" style="margin:0 0 8px 0;font-family:'Chakra Petch','Bahnschrift','Segoe UI',Arial,sans-serif;font-size:11px;font-weight:700;letter-spacing:2.5px;color:#a0a7b4">DOĞRULAMA KODU</p><p class="code" style="margin:0;font-size:36px;line-height:1.2;letter-spacing:10px;font-weight:700;font-family:Consolas,Menlo,'Courier New',monospace;color:#ff2e88">{{code}}</p></td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:4px 0 0 0"><tr><td class="note" style="padding:14px 18px;background:#1e1f26;border-left:4px solid #ff2e88;border-radius:6px;font-size:14px;line-height:1.55">Bu isteği sen yapmadıysan bu e-postayı yok sayabilirsin. Kodu kimseyle paylaşma.</td></tr></table>$h$,
 $x$LTZ doğrulama kodun: {{code}}
Kod {{validityMinutes}} dakika geçerli.
Bu isteği sen yapmadıysan bu e-postayı yok say. Kodu kimseyle paylaşma.$x$),
('EMAIL_VERIFICATION', 'en',
 $s$Your LTZ email verification code$s$,
 $h$<p class="eb-accent" style="margin:0 0 10px 0;font-family:'Chakra Petch','Bahnschrift','Segoe UI',Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:2.5px;color:#ff2e88">EMAIL VERIFICATION</p><h1 class="h1" style="margin:0 0 16px 0;font-family:'Chakra Petch','Bahnschrift','Segoe UI',Arial,sans-serif;font-size:28px;line-height:1.2;font-weight:700;color:#f1f1f1">Verify your email address</h1><p style="margin:0 0 18px 0">Enter the code below to verify your LTZ account. The code is valid for {{validityMinutes}} minutes.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 20px 0"><tr><td class="box" align="center" style="padding:20px 16px;background:#1e1f26;border:1px solid #34343c;border-radius:12px"><p class="muted" style="margin:0 0 8px 0;font-family:'Chakra Petch','Bahnschrift','Segoe UI',Arial,sans-serif;font-size:11px;font-weight:700;letter-spacing:2.5px;color:#a0a7b4">VERIFICATION CODE</p><p class="code" style="margin:0;font-size:36px;line-height:1.2;letter-spacing:10px;font-weight:700;font-family:Consolas,Menlo,'Courier New',monospace;color:#ff2e88">{{code}}</p></td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:4px 0 0 0"><tr><td class="note" style="padding:14px 18px;background:#1e1f26;border-left:4px solid #ff2e88;border-radius:6px;font-size:14px;line-height:1.55">If you did not make this request you can ignore this email. Never share the code with anyone.</td></tr></table>$h$,
 $x$Your LTZ verification code: {{code}}
The code is valid for {{validityMinutes}} minutes.
If you did not make this request, ignore this email. Never share the code with anyone.$x$),
('PASSWORD_RESET_LINK', 'tr',
 $s$LTZ parola sıfırlama$s$,
 $h$<p class="eb-accent" style="margin:0 0 10px 0;font-family:'Chakra Petch','Bahnschrift','Segoe UI',Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:2.5px;color:#ff2e88">PAROLA SIFIRLAMA</p><h1 class="h1" style="margin:0 0 16px 0;font-family:'Chakra Petch','Bahnschrift','Segoe UI',Arial,sans-serif;font-size:28px;line-height:1.2;font-weight:700;color:#f1f1f1">Parolanı sıfırla</h1><p style="margin:0 0 18px 0">LTZ parolanı sıfırlamak için aşağıdaki düğmeyi kullan. Bağlantı {{validityMinutes}} dakika geçerli ve yalnız bir kez kullanılabilir.</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 0 18px 0"><tr><td bgcolor="#e11d2e" style="background:#e11d2e;border-radius:10px"><a href="{{link}}" style="display:inline-block;padding:14px 32px;font-family:'Chakra Petch','Bahnschrift','Segoe UI',Arial,sans-serif;font-size:15px;font-weight:700;letter-spacing:0.5px;line-height:1.2;color:#ffffff;text-decoration:none;border-radius:10px;background:#e11d2e">Parolayı sıfırla</a></td></tr></table><p class="muted" style="margin:0 0 22px 0;font-size:13px;line-height:1.5;color:#a0a7b4">Düğme çalışmazsa bu adresi tarayıcına yapıştır:<br><span style="word-break:break-all">{{link}}</span></p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:4px 0 0 0"><tr><td class="note" style="padding:14px 18px;background:#1e1f26;border-left:4px solid #f59e0b;border-radius:6px;font-size:14px;line-height:1.55">Bu isteği sen yapmadıysan bu e-postayı yok say; parolan değişmez.</td></tr></table>$h$,
 $x$LTZ parolanı sıfırlamak için bağlantıyı aç ({{validityMinutes}} dakika geçerli, tek kullanımlık):
{{link}}

Bu isteği sen yapmadıysan bu e-postayı yok say; parolan değişmez.$x$),
('PASSWORD_RESET_LINK', 'en',
 $s$LTZ password reset$s$,
 $h$<p class="eb-accent" style="margin:0 0 10px 0;font-family:'Chakra Petch','Bahnschrift','Segoe UI',Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:2.5px;color:#ff2e88">PASSWORD RESET</p><h1 class="h1" style="margin:0 0 16px 0;font-family:'Chakra Petch','Bahnschrift','Segoe UI',Arial,sans-serif;font-size:28px;line-height:1.2;font-weight:700;color:#f1f1f1">Reset your password</h1><p style="margin:0 0 18px 0">Use the button below to reset your LTZ password. The link is valid for {{validityMinutes}} minutes and can be used only once.</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 0 18px 0"><tr><td bgcolor="#e11d2e" style="background:#e11d2e;border-radius:10px"><a href="{{link}}" style="display:inline-block;padding:14px 32px;font-family:'Chakra Petch','Bahnschrift','Segoe UI',Arial,sans-serif;font-size:15px;font-weight:700;letter-spacing:0.5px;line-height:1.2;color:#ffffff;text-decoration:none;border-radius:10px;background:#e11d2e">Reset password</a></td></tr></table><p class="muted" style="margin:0 0 22px 0;font-size:13px;line-height:1.5;color:#a0a7b4">If the button does not work, paste this address into your browser:<br><span style="word-break:break-all">{{link}}</span></p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:4px 0 0 0"><tr><td class="note" style="padding:14px 18px;background:#1e1f26;border-left:4px solid #f59e0b;border-radius:6px;font-size:14px;line-height:1.55">If you did not make this request, ignore this email; your password will not change.</td></tr></table>$h$,
