 $h$<p class="eb-warn" style="margin:0 0 10px 0;font-family:'Chakra Petch','Bahnschrift','Segoe UI',Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:2.5px;color:#f59e0b">GÜVENLİK BİLDİRİMİ</p><h1 class="h1" style="margin:0 0 16px 0;font-family:'Chakra Petch','Bahnschrift','Segoe UI',Arial,sans-serif;font-size:28px;line-height:1.2;font-weight:700;color:#f1f1f1">Parolan değiştirildi</h1><p style="margin:0 0 18px 0">LTZ hesabının parolası değiştirildi.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 22px 0"><tr><td class="box" style="padding:13px 18px;background:#1e1f26;border:1px solid #34343c;border-radius:10px;font-size:14px"><span class="muted" style="color:#a0a7b4">Tarih:</span>&nbsp;&nbsp;<strong>{{occurredAt}}</strong></td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:4px 0 0 0"><tr><td class="note" style="padding:14px 18px;background:#1e1f26;border-left:4px solid #f59e0b;border-radius:6px;font-size:14px;line-height:1.55">Bu değişikliği sen yapmadıysan hemen "Parolamı unuttum" ile parolanı sıfırla.</td></tr></table>$h$,
